def compute_accuracy(preds, actuals):
    correct = total = 0
    for p, a in zip(preds, actuals):
        if p == 250:               # skip missing-data cases
            continue
        total += 1
        if p == a:
            correct += 1
    return correct / total if total > 0 else 0

print(f"XGBoost accuracy:      {compute_accuracy(xgboost, actual):.2%}")
print(f"Transformer accuracy:  {compute_accuracy(transformer, actual):.2%}")
print(f"XGBoost2 accuracy:     {compute_accuracy(xgb2, actual):.2%}")
print(f"XGBoost6638 accuracy:  {compute_accuracy(xgb6638, actual):.2%}")